all_items = _items

input1_items = []
input2_items = []
input3_items = []
master_items = []

for item in all_items:
    if isinstance(item, dict):
        d = item.get("json", item)
    else:
        d = item.json if hasattr(item, "json") else item

    if not isinstance(d, dict):
        continue

    keys = d.keys()

    if "Score" in keys and "Kode AHASS" in keys:
        input1_items.append(d)
    elif "NO. AHASS" in keys or "TOTAL LEAD MEASURE" in keys or "LEAD MEASURE" in keys:
        input2_items.append(d)
    elif "Overall CRM Effectiveness" in keys or "Ecosystem Health" in keys:
        input3_items.append(d)
    elif "Pareto" in keys and "No AHASS" in keys:
        master_items.append(d)

def clean(val):
    return str(val).strip() if val is not None else ""

def parse_float(val):
    try:
        s = clean(val).upper()
        if s in ["", "N/A", "-", "NONE"]:
            return float("inf")
        return float(s.replace(",", "."))
    except:
        return float("inf")

# 1. Referensi Master dari sheet 'data AHASS untuk sharla'
master_map = {}
for row in master_items:
    no_ahass = clean(row.get("No AHASS"))
    if no_ahass:
        master_map[no_ahass] = {
            "pareto": clean(row.get("Pareto")).lower(),
            "nama_resmi": clean(row.get("Nama AHASS"))
        }

def get_top_2_strict(grouped_list):
    grouped_list.sort(key=lambda x: x["score"])
    return grouped_list[:2]

# ==============================================================================
# 1. INPUT 1: PERFORMANCE
# ==============================================================================
kpi_perf_order = {"CRITICAL": 1, "RISK": 2, "WARNING": 3, "SUSTAIN": 4}
group_perf = {}

for data in input1_items:
    no_h2 = clean(data.get("Kode AHASS"))
    status = clean(data.get("Status")).upper()
    area_g = clean(data.get("Area"))
    skor_h = parse_float(data.get("Score"))

    if not no_h2:
        continue

    info = master_map.get(no_h2, {
        "pareto": clean(data.get("Pareto") or "non pareto").lower(),
        "nama_resmi": clean(data.get("Nama AHASS"))
    })

    if no_h2 not in group_perf or skor_h < group_perf[no_h2]["score"]:
        group_perf[no_h2] = {
            "Pareto": info["pareto"].title(),
            "No AHASS": no_h2,
            "Nama AHASS": info["nama_resmi"] if info["nama_resmi"] else clean(data.get("Nama AHASS")),
            "KPI": status if status else "WARNING",
            "Keterangan": area_g if area_g else status,
            "Nama Dashboard": "Performance",
            "score": skor_h
        }

top2_performance = get_top_2_strict(list(group_perf.values()))

# ==============================================================================
# 2. INPUT 2: SPAREPART (Urutan KPI: Critical -> Risk -> Warning -> Sustain)
# (Urutan Fokus Area/Keterangan: PROSES -> PRIMESES -> PEOPLE -> PROMOSI)
# ==============================================================================
sparepart_kpi_order = {"CRITICAL": 1, "RISK": 2, "WARNING": 3, "SUSTAIN": 4}
fokus_area_order = {"PROSES": 1, "PRIMESES": 2, "PEOPLE": 3, "PROMOSI": 4}

group_sparepart = {}

for data in input2_items:
    no_h2 = clean(data.get("NO. AHASS"))
    skor_br = parse_float(data.get("TOTAL LEAD MEASURE") or data.get("LEAD MEASURE"))
    final_kpi = clean(data.get("FINAL") or data.get("LAG MEASURE") or "CRITICAL").upper()
    fokus_area = clean(data.get("FOKUS AREA") or data.get("Chanel") or "PROSES").upper()

    if not no_h2:
        continue

    info = master_map.get(no_h2, {
        "pareto": "non pareto",
        "nama_resmi": clean(data.get("Nama AHASS"))
    })

    if no_h2 not in group_sparepart or skor_br < group_sparepart[no_h2]["score"]:
        group_sparepart[no_h2] = {
            "Pareto": info["pareto"].title(),
            "No AHASS": no_h2,
            "Nama AHASS": info["nama_resmi"] if info["nama_resmi"] else clean(data.get("Nama AHASS")),
            "KPI": final_kpi,
            "Keterangan": fokus_area,
            "Nama Dashboard": "Sparepart",
            "score": skor_br,
            "kpi_rank": sparepart_kpi_order.get(final_kpi, 99),
            "fokus_rank": fokus_area_order.get(fokus_area, 99)
        }

# Urutkan Sparepart berdasarkan prioritas KPI terburuk, lalu prioritas Fokus Area, lalu skor terendah
sparepart_list = list(group_sparepart.values())
sparepart_list.sort(key=lambda x: (x["kpi_rank"], x["fokus_rank"], x["score"]))
top2_sparepart = sparepart_list[:2]

# ==============================================================================
# 3. INPUT 3: CRM
# ==============================================================================
kpi_crm_order = {"BRONZE": 1, "SILVER": 2, "GOLD": 3, "PLATINUM": 4}
ecosystem_order = {"QUALITY CHECK CRM": 1, "BUTUH TEAM ASSIST": 2, "CRM HEALTHY": 3}
list_crm = []
seen_crm = set()

for data in input3_items:
    no_h2 = clean(data.get("No H2") or data.get("Kode AHASS") or data.get("No AHASS"))
    crm_aa = clean(data.get("Overall CRM Effectiveness")).upper()
    health_ab = clean(data.get("Ecosystem Health")).upper()

    if not no_h2 or no_h2 in seen_crm:
        continue
    seen_crm.add(no_h2)

    info = master_map.get(no_h2, {
        "pareto": "non pareto",
        "nama_resmi": clean(data.get("Dealer Name") or data.get("Nama AHASS"))
    })

    list_crm.append({
        "Pareto": info["pareto"].title(),
        "No AHASS": no_h2,
        "Nama AHASS": info["nama_resmi"] if info["nama_resmi"] else clean(data.get("Dealer Name")),
        "KPI": crm_aa if crm_aa else "SILVER",
        "Keterangan": health_ab if health_ab else "QUALITY CHECK CRM",
        "Nama Dashboard": "CRM",
        "rank": kpi_crm_order.get(crm_aa, 99)
    })

list_crm.sort(key=lambda x: x["rank"])
top2_crm = list_crm[:2]

# ==============================================================================
# 4. GABUNGKAN TOTAL 6 BARIS (2 Performance + 2 Sparepart + 2 CRM)
# ==============================================================================
total_6_items = top2_performance + top2_sparepart + top2_crm

result = []
for d in total_6_items:
    result.append({
        "json": {
            "Pareto": d["Pareto"],
            "No AHASS": d["No AHASS"],
            "Nama AHASS": d["Nama AHASS"],
            "KPI": d["KPI"],
            "Keterangan": d["Keterangan"],
            "Nama Dashboard": d["Nama Dashboard"]
        }
    })

return result
